package com.wms.service;
import com.fasterxml.jackson.databind.ObjectMapper;import com.wms.common.BizException;import com.wms.entity.PendingBusinessAction;import com.wms.repository.PendingBusinessActionRepository;import org.springframework.stereotype.Service;import java.time.*;import java.time.format.DateTimeFormatter;
@Service public class PendingBusinessActionService{public record Submission(PendingBusinessAction action,boolean completed){}private final PendingBusinessActionRepository repo;private final ApprovalService approvals;private final ObjectMapper json;public PendingBusinessActionService(PendingBusinessActionRepository r,ApprovalService a,ObjectMapper j){repo=r;approvals=a;json=j;}public Submission submit(String type,Long sourceId,String prefix,String applicant,Object payload){if(repo.existsByBusinessTypeAndSourceIdAndStatus(type,sourceId,"PENDING"))throw new BizException("该业务已有待审批申请");PendingBusinessAction a=new PendingBusinessAction();a.setBusinessType(type);a.setSourceId(sourceId);a.setBusinessNo(prefix+LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMddHHmmssSSS")));a.setCreatedBy(applicant);a.setStatus("PENDING");try{a.setPayload(json.writeValueAsString(payload));}catch(Exception e){throw new BizException("申请数据保存失败");}repo.save(a);var approval=approvals.submit(type,a.getId(),a.getBusinessNo(),applicant);return new Submission(a,approval.getStatus()==com.wms.entity.ApprovalStatus.APPROVED);}public PendingBusinessAction pending(Long id){return repo.findByIdAndStatus(id,"PENDING").orElseThrow(()->new BizException("待审批业务不存在或已处理"));}public <T>T payload(PendingBusinessAction a,Class<T> type){try{return json.readValue(a.getPayload(),type);}catch(Exception e){throw new BizException("申请数据解析失败");}}public void finish(PendingBusinessAction a,String status){a.setStatus(status);a.setFinishedAt(Instant.now());repo.save(a);}}
